import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Extract text content
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textItem = items.find((item) => item.role === 'headline') || items[0];
  const textContent = textItem?.text ?? 'Pricing 2';

  // Atlas region dimensions (from spec)
  const atlasWidth = 512;
  const atlasHeight = 320;
  const aspectRatio = atlasWidth / atlasHeight;

  // Create plane geometry sized to aspect ratio
  // Use a small scale to fit in scene; adjust height to control visibility
  const planeWidth = aspectRatio * 1.2; // 1.92 units wide
  const planeHeight = 1.2; // 1.2 units tall
  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  // Load the ceramic grain texture
  const group = new THREE.Group();
  const timeline = [];
  const cleanupFns = [];

  ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
    // Configure texture for atlas region
    texture.magFilter = THREE.LinearFilter;
    texture.minFilter = THREE.LinearMipMapLinearFilter;
    texture.flipY = false;

    // UV offset for atlas region (0, 0, 512, 320) in a larger atlas
    // Assuming atlas is 2048x2048 or similar; adjust if needed
    const uvOffset = new THREE.Vector2(0, 0); // top-left
    const uvScale = new THREE.Vector2(1, 1); // full region

    texture.offset.copy(uvOffset);
    texture.repeat.copy(uvScale);

    // Create material with TSL nodes for flexibility
    const material = new MeshBasicNodeMaterial({
      map: texture,
      color: 0xffffff,
      transparent: true,
      side: THREE.DoubleSide,
      toneMapped: false,
    });

    // Create mesh
    const mesh = new THREE.Mesh(geometry, material);
    mesh.castShadow = false;
    mesh.receiveShadow = false;

    // Billboard toward camera (always face forward)
    mesh.position.copy(config.scenePosition || new THREE.Vector3(0, 1, 0.06));
    mesh.quaternion.setFromEuler(
      new THREE.Euler(0, 0, 0, 'XYZ')
    );

    group.add(mesh);

    // Render text label on top
    if (textContent && ctx.fontAtlas) {
      const textMesh = ctx.fontAtlas.createText(textContent, {
        fontSize: 39,
        color: '#16161d', // ink
        align: 'center',
        letterSpacingPx: 0,
      });

      if (textMesh) {
        textMesh.position.z = 0.1; // Slight offset forward
        textMesh.scale.set(0.85, 0.85, 1); // Scale down to fit card
        group.add(textMesh);
      }
    }
  });

  // Setup cleanup
  group.userData.cleanup = () => {
    timeline.forEach((t) => t.kill());
    cleanupFns.forEach((fn) => fn());
    geometry.dispose();
  };

  group.userData.handlers = {};

  return group;
}
